+/** Theoretical sales use and actual ledger use for an inclusive UTC date range. */
+export function varianceReport(store, from, to) {
+  if (from > to) throw new AppError("bad_request", { reason: "from must be on or before to" });
+  const inRange = (at) => {
+    const day = dayOf(at);
+    return day >= from && day <= to;
+  };
+  const theoretical = new Map();
+  const actual = new Map();
+  for (const sale of store.data.sales) {
+    if (!inRange(sale.soldAt)) continue;
+    for (const { itemId, qty } of sale.ingredients) {
+      theoretical.set(itemId, (theoretical.get(itemId) ?? 0) + Math.round(qty * 1000));
+    }
+  }
+  const batchItems = new Map(store.data.batches.map((batch) => [batch.id, batch.itemId]));
+  for (const movement of store.data.movements) {
+    if (movement.type !== "consume" || !inRange(movement.at)) continue;
+    const itemId = batchItems.get(movement.batchId);
+    if (itemId === undefined) continue;
+    actual.set(itemId, (actual.get(itemId) ?? 0) + Math.round(movement.qty * 1000));
+  }
+  const itemIds = new Set([...theoretical.keys(), ...actual.keys()]);
+  return [...itemIds].sort((a, b) => a - b).flatMap((itemId) => {
+    const expected = theoretical.get(itemId) ?? 0;
+    const used = actual.get(itemId) ?? 0;
+    if (expected <= 0 && used <= 0) return [];
+    return [{ itemId, theoretical: expected / 1000, actual: used / 1000, variance: (used - expected) / 1000 }];
+  });
+}
