@@ -0,0 +1,34 @@
+import { memoryStore } from "../db/store.js";
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+/** Records new sales and their ingredient usage as one stock operation. */
+export function recordSales(store, sales) {
+  const staged = memoryStore(store.data);
+  const imported = new Set(staged.data.sales.map((sale) => sale.ticket));
+  const tickets = new Set();
+  let dishes = 0;
+  for (const { row, ticket, soldAt, dishId, qty } of sales) {
+    if (imported.has(ticket)) continue;
+    let ingredients;
+    try {
+      const dish = getDish(staged, dishId);
+      ingredients = scaled(getRecipe(staged, dish.recipeId), qty).filter((ingredient) => ingredient.qty > 0);
+      for (const ingredient of ingredients) {
+        consume(staged, ingredient.itemId, ingredient.qty, { at: soldAt, ref: `sale:${ticket}` });
+      }
+    } catch (error) {
+      if (!(error instanceof AppError)) throw error;
+      if (error.code === "not_enough_stock")
+        throw new AppError("not_enough_stock", { ...error.params, row });
+      throw new AppError("bad_request", { reason: `row ${row}: invalid dish or recipe ingredients for dish ${dishId}` });
+    }
+    staged.data.sales.push({ ticket, soldAt, dishId, qty, ingredients });
+    tickets.add(ticket);
+    dishes += qty;
+  }
+  if (tickets.size) store.data = staged.data;
+  return { tickets: tickets.size, dishes };
+}
