diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..07f089f
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,40 @@
+import { isDate } from "../dates.js";
+import { AppError } from "../errors.js";
+import { parseCsv } from "./csv.js";
+import { recordSales } from "../domain/sales.js";
+
+const columns = ["ticket", "soldAt", "dishId", "qty"];
+const field = '(?:"(?:[^"]|"")*"|[^",]*)';
+const csvLine = new RegExp(`^${field}(?:,${field})*$`);
+const instant = /^\d{4}-\d{2}-\d{2}T(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|[+-](?:[01]\d|2[0-3]):[0-5]\d)$/;
+
+function invalid(row, reason) {
+  return new AppError("bad_request", { reason: `row ${row}: ${reason}` });
+}
+
+/** Validates till CSV and imports all new tickets atomically. */
+export function importSales(store, text) {
+  const [header, ...lines] = text.split(/\r?\n/);
+  const keys = parseCsv(header)[0]?.map((key) => key.trim()) ?? [];
+  if (!csvLine.test(header) || keys.length !== columns.length || !columns.every((key) => keys.includes(key)))
+    throw invalid(1, "expected ticket,soldAt,dishId,qty");
+
+  const sales = [];
+  for (const [index, line] of lines.entries()) {
+    if (!line.trim()) continue;
+    const row = index + 2;
+    if (!csvLine.test(line)) throw invalid(row, "malformed CSV");
+    const [fields] = parseCsv(line);
+    if (fields.length !== keys.length) throw invalid(row, "expected four fields");
+    const { ticket, soldAt, dishId, qty } = Object.fromEntries(keys.map((key, i) => [key, fields[i].trim()]));
+    if (!ticket) throw invalid(row, "ticket is required");
+    if (!instant.test(soldAt) || !isDate(soldAt.slice(0, 10)) || !Number.isFinite(Date.parse(soldAt)))
+      throw invalid(row, "soldAt must be an ISO instant");
+    if (!/^\d+$/.test(dishId) || !Number.isSafeInteger(Number(dishId)) || Number(dishId) < 1)
+      throw invalid(row, "dishId must be a positive whole number");
+    if (!/^\d+$/.test(qty) || !Number.isSafeInteger(Number(qty)) || Number(qty) < 1)
+      throw invalid(row, "qty must be a positive whole number");
+    sales.push({ row, ticket, soldAt: new Date(soldAt).toISOString(), dishId: Number(dishId), qty: Number(qty) });
+  }
+  return recordSales(store, sales);
+}
